/**
 * Brain-Co Reference-Extracted 3D Anatomical Brain Dataset
 * Source: models/original/brain.glb (Z-Anatomy / DBCLS TA2 Gross Anatomy)
 * Extracted parenchymal meshes: 448 (cerebral cortex, cerebellar folia, brainstem)
 * Shard Count: 16000
 */

export const SHARD_COUNT = 16000;

export const BRAIN_COORDS_B64 = "";

export const BRAIN_NORMALS_B64 = "";

export const BRAIN_PARAMS_B64 = "";

export function decodeBase64Float32(b64: string): Float32Array {
  if (typeof window === "undefined") {
    const buf = Buffer.from(b64, "base64");
    return new Float32Array(buf.buffer, buf.byteOffset, buf.byteLength / 4);
  }
  const binary = atob(b64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) {
    bytes[i] = binary.charCodeAt(i);
  }
  return new Float32Array(bytes.buffer);
}
